pub type OH_AVMediaSourceLoaderOnSourceReadCallback = ::std::option::Option<
    unsafe extern "C" fn(
        uuid: i64,
        requestedOffset: i64,
        requestedLength: i64,
        userData: *mut ::std::os::raw::c_void,
    ),
>;
#[doc = " @brief Defines the SourceCloseCallback function which is called by the service.\n Client should release related resources.\n The client must return the handle immediately after processing the request.\n @param uuid ID for the resource handle.\n @param userData The data set by user in OH_AVMediaSourceLoader_SetSourceCloseCallback\n @since 23"]
